import{_ as a,o as s,c as n,a5 as r}from"./chunks/framework.DfywBLEo.js";const h=JSON.parse('{"title":"文章标题与目录","description":"","frontmatter":{},"headers":[],"relativePath":"guide/articleDirectory.md","filePath":"guide/articleDirectory.md","lastUpdated":1792557099000}'),o={name:"guide/articleDirectory.md"};function c(l,e,t,i,p,d){return s(),n("div",null,[...e[0]||(e[0]=[r(`<h1 id="文章标题与目录" tabindex="-1">文章标题与目录 <a class="header-anchor" href="#文章标题与目录" aria-label="Permalink to &quot;文章标题与目录&quot;">​</a></h1><p>插件会读取正文中的 <code>h1</code>～<code>h6</code> 标题，生成文章目录。Markdown 中的 <code>#</code>～<code>######</code> 会生成相应标题，加粗文本不会生成目录。</p><h2 id="标题层级" tabindex="-1">标题层级 <a class="header-anchor" href="#标题层级" aria-label="Permalink to &quot;标题层级&quot;">​</a></h2><p>建议按顺序使用标题，避免跳级。例如：</p><div class="language-markdown line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">markdown</span><pre class="shiki simplememory-plum vp-code" tabindex="0"><code><span class="line"><span style="color:#EEE6F7;">## 安装</span></span>
<span class="line"><span style="color:#EEE6F7;">### 后台设置</span></span>
<span class="line"><span style="color:#EEE6F7;">### 插件配置</span></span>
<span class="line"><span style="color:#EEE6F7;">## 使用</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><p>目录以文章中实际出现的标题级别排序并缩进。如果整篇文章只有 <code>h2</code> 和 <code>h4</code>，目录会显示为两层，不为缺失的 <code>h3</code> 保留一层。</p><h2 id="位置和显示" tabindex="-1">位置和显示 <a class="header-anchor" href="#位置和显示" aria-label="Permalink to &quot;位置和显示&quot;">​</a></h2><p>目录默认在右侧。屏幕宽度达到隐藏阈值，或正文两侧空间不足时，会自动隐藏；可以通过右下角的目录按钮尝试显示。</p><p>位置、隐藏宽度、横向滚动条和编号的设置见<a href="/Cnblogs-Theme-SimpleMemory/v2.1/dist/reference/config/article.html#articledirectory-文章目录">文章目录配置</a>。</p>`,9)])])}const u=a(o,[["render",c]]);export{h as __pageData,u as default};
